/bin/bash -lc "python3 -B -c 'import json
from pathlib import Path
p = Path(\"enrichment/v7/work/t1_s087_20261009/out/luna-max/c645.jsonl\")
fixes = {
    \"QURTUBI-FULL:7:169\": {
        7: \"وقال آخر:\\nإنا وجدنا خلفا بئس الخلف\\nأغلق عنا بابه ثم حلف\"
    },
    \"QURTUBI-FULL:7:201-202#3\": {
        1: \"وحكي عن محمد بن يزيد أنه احتج لقراءة أهل المدينة قال: يقال مددت له في كذا أي زينته له\"
    },
    \"QURTUBI-FULL:8:24\": {
        4: \"متعلق بقوله: «استجيبوا». المعنى: استجيبوا لما يحييكم إذا دعاكم. وقيل: اللام بمعنى إلى،\",
        13: \"فبان بهذا النص أنه تعالى خالق لجميع اكتساب العباد خيرها وشرها.\"
    },
    \"QURTUBI-FULL:8:24#2\": {
        1: \"\\\" لا، ومقلب القلوب \\\"\\nوكان فعل الله تعالى ذلك عدلا\",
        4: \"والقلب موضع الفكر. وقد تقدم في «البقرة» بيانه. وهو بيد الله، متى شاء حال بين العبد وبينه بمرض أو آفة\"
    },
    \"QURTUBI-FULL:8:42\": {
        3: \"والدنيا: تأنيث الأدنى. والقصوى: تأنيث الأقصى. من دنا يدنو، وقصا يقصو. ويقال: القصيا. والأصل الواو، وهي لغة أهل الحجاز قصوى.\",
        7: \"«الركب» ابتداء «أسفل منكم» ظرف في موضع الخبر. أي مكانا أسفل منكم.\",
        13: \"«من» في موضع رفع. «ويحيا» في موضع نصب عطف على ليهلك.\"
    }
}
lines = p.read_text().splitlines(keepends=True)
changed = 0
for i, line in enumerate(lines):
    record = json.loads(line)
    for n, anchor in fixes.get(record[\"loc\"], {}).items():
        row = record[\"rows\"][n - 1]
        old = json.dumps(row[\"anchor\"], ensure_ascii=False)
        new = json.dumps(anchor, ensure_ascii=False)
        assert line.count(old) == 1, (record[\"loc\"], n)
        line = line.replace(old, new, 1)
        row[\"anchor\"] = anchor
        changed += 1
    assert json.loads(line) == record
    lines[i] = line
assert changed == 9, changed
p.write_text(\"\".join(lines))
print(\"Changed exactly 9 anchor fields; preserved all other content.\")
'"

